md<-qread(out('00_audit/cell_metadata.qs'));cov<-fread(out('02_coverage/candidate_source_coverage.tsv'));can<-fread(out('03_candidates/candidates_preDE.tsv'));cts<-fread(out('03_candidates/comparisons_preDE.tsv'));bas<-list();qc<-list()
for(field in c('sample','dataset','source'))for(h in c('NMF','UCell')){d<-data.table(level=as.character(md[[field]]),sel=md$r04=='C8',hi=md[[paste0(h,'_high')]])[,.(old_n_candidate=sum(sel),old_TP=sum(sel&hi),n_pool=.N,n_high=sum(hi)),by=level];d[,`:=`(old_precision=ifelse(old_n_candidate>0,old_TP/old_n_candidate,NA_real_),old_recall=ifelse(n_high>0,old_TP/n_high,NA_real_),field=field,high=h)];bas[[length(bas)+1L]]<-d};b<-rbindlist(bas);wt(b,'02_coverage/old_C8_source_coverage.tsv');d<-merge(cov,b[,.(level,field,high,old_n_candidate,old_TP,old_precision,old_recall)],by=c('level','field','high'));d[,`:=`(delta_P=precision-old_precision,delta_R=recall-old_recall)];d[,comparison_status:=ifelse(is.na(delta_P)|is.na(delta_R),'NA_denominator',ifelse(delta_P>=0&delta_R>=0&(delta_P>0|delta_R>0),'both_improve_or_one_equal',ifelse(delta_P>0|delta_R>0,'tradeoff','neither_improves')))];wt(d,'02_coverage/all_candidate_source_vs_C8.tsv');wt(d[,.(n_levels=.N,n_valid=sum(is.finite(delta_P)&is.finite(delta_R)),n_P_up=sum(delta_P>0,na.rm=TRUE),n_R_up=sum(delta_R>0,na.rm=TRUE),n_joint_up=sum(comparison_status=='both_improve_or_one_equal'),n_NA=sum(comparison_status=='NA_denominator')),by=.(candidate_id,field,high)],'02_coverage/source_improvement_summary.tsv')
last<-NULL
for(i in 1:nrow(cts)){c<-cts[i];if(!identical(last,c$partition)){lab<-qread(out(paste0('01_partitions/',c$partition,'.qs')));last<-c$partition};L<-lab$cluster==c$cluster;R<-if(is.na(c$control_cluster))rep(FALSE,nrow(md))else if(c$control_cluster=='rest')!L else lab$cluster==c$control_cluster;d<-copy(md);d[,group:=ifelse(L,'Left',ifelse(R,'Right',NA_character_))];n<-d[!is.na(group),.N,by=.(sample,group)];q<-d[!is.na(group),.(n=.N,nCount=mean(nCount_counts),nFeature=mean(nFeature_counts),percent_mt=if(all(is.na(percent.mt)))NA_real_ else mean(percent.mt,na.rm=TRUE)),by=.(sample,dataset,source,group)];if(!all(c('Left','Right')%in%q$group))next;w<-dcast(q,sample+dataset+source~group,value.var=c('n','nCount','nFeature','percent_mt'));w[,`:=`(comparison_id=c$comparison_id,candidate_id=c$candidate_id,eligible=n_Left>=30&n_Right>=30,delta_nCount=nCount_Left-nCount_Right,delta_nFeature=nFeature_Left-nFeature_Right,delta_percent_mt=percent_mt_Left-percent_mt_Right)];qc[[length(qc)+1L]]<-w};q<-rbindlist(qc,fill=TRUE);wt(q,'08_review/paired_QC_sample_differences.tsv');wt(q[eligible==TRUE,.(n_pairs=.N,nCount_positive=sum(delta_nCount>0),nFeature_positive=sum(delta_nFeature>0),mt_positive=sum(delta_percent_mt>0,na.rm=TRUE),nCount_median_delta=median(delta_nCount),nFeature_median_delta=median(delta_nFeature),mt_median_delta=median(delta_percent_mt,na.rm=TRUE)),by=.(candidate_id,comparison_id)],'08_review/paired_QC_summary.tsv');logmsg('Source changes and paired QC complete')
